DROP TABLE IF EXISTS shop.ticket;
CREATE TABLE shop.ticket (id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, note VARCHAR(32) NOT NULL) ENGINE=InnoDB;
INSERT INTO shop.ticket (note) VALUES ('seed');
ALTER TABLE shop.ticket AUTO_INCREMENT = 4294967295;
INSERT INTO shop.ticket (note) VALUES ('last-one')

GRANT EXECUTE ON shop.* TO 'app'@'%';
DROP PROCEDURE IF EXISTS shop.ticket_issue;
DELIMITER //
CREATE PROCEDURE shop.ticket_issue(n INT) SQL SECURITY INVOKER
BEGIN
  DECLARE i INT DEFAULT 0;
  DECLARE CONTINUE HANDLER FOR SQLEXCEPTION BEGIN END;
  WHILE i < n DO
    INSERT INTO shop.ticket (note) VALUES (CONCAT('req-', i));
    DO SLEEP(1);
    SET i = i + 1;
  END WHILE;
END//
DELIMITER ;
